const gpIdLookup = new Map<string, string>(
  OFFICIAL_PRIORITY_GRAM_PANCHAYATS.map(gp => [`${gp.blockName.toLowerCase()}::${gp.name.toLowerCase()}`, gp.id])
);

export const OFFICIAL_PRIORITY_VILLAGES: RuralVillageMouzaRecord[] = RAW_OFFICIAL_VILLAGES.map((v, idx) => {
  const gpId = gpIdLookup.get(`${v.blockName.toLowerCase()}::${v.gpName.toLowerCase()}`) || `GP-${v.blockName.toUpperCase()}`;
  return {
    id: `VIL-OFF-${String(idx + 1).padStart(4, '0')}`,
    name: v.name,
    mouzaName: v.mouzaName,
    jlNo: v.jlNo,
    gpId,
    gpName: v.gpName,
    blockName: v.blockName,
    subdivisionName: 'Domkal',
    district: 'Murshidabad',
    postOffice: v.postOffice,
    policeStation: v.policeStation,
    pinCode: v.pinCode,
    verificationStatus: 'VERIFIED',
    sourceName: 'Census 2011 WB LGD + India Post Verified'
  };
});
